280	 * @throws Error if name collision exists or batch publish fails
281	 */
282	export async function addFileToFolder(params: {
283	  children: FolderChild[];
284	  folderKey: Uint8Array;
285	  ipnsPrivateKey: Uint8Array;
286	  ipnsPublicKey?: Uint8Array;
287	  ipnsName: string;
288	  sequenceNumber: bigint;
289	  fileId: string;
290	  name: string;
291	  fileIpnsRecord: FileIpnsRecordPayload;
292	  ipnsPrivateKeyEncrypted: string;
293	  ctx: SdkContext;
294	}): Promise<{ filePointer: FilePointer; newSequenceNumber: bigint }> {
295	  // 1. Check for name collision
296	  const nameExists = params.children.some((c) => c.name === params.name);
297	  if (nameExists) {
298	    throw new Error('A file with this name already exists');
299	  }
300	
301	  // 2. Create FilePointer
302	  const now = Date.now();
303	  const filePointer: FilePointer = {
304	    type: 'file',
305	    id: params.fileId,
306	    name: params.name,
307	    fileMetaIpnsName: params.fileIpnsRecord.ipnsName,
308	    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
309	    createdAt: now,
310	    modifiedAt: now,
311	  };
312	
313	  // 3. Add FilePointer to parent's children
314	  const children: FolderChild[] = [...params.children, filePointer];
315	
316	  // 4. Build folder IPNS record for batch publish
317	  const folderResult = await buildFolderIpnsRecord({
