1	/**
2	 * @cipherbox/sdk - Bin operations
3	 *
4	 * Extracted from: apps/web/src/services/bin.service.ts (962 LOC)
5	 * All Zustand store access replaced with explicit parameters.
6	 *
7	 * Bin operations manage the recycle bin lifecycle:
8	 * - addToBin: soft-delete (remove from folder, add to bin)
9	 * - restoreFromBin: undo soft-delete (remove from bin, add back to folder)
10	 * - permanentDeleteFromBin: hard-delete with CID cleanup
11	 * - emptyBin: permanently delete all bin entries
12	 * - loadBin: load current bin metadata from IPNS
13	 *
14	 * Each function takes explicit params instead of reading from stores.
15	 */
16	
17	import type { SdkContext, TeeKeys } from '@cipherbox/sdk-core';
18	import * as sdkCore from '@cipherbox/sdk-core';
19	import {
20	  encryptBinMetadata,
21	  decryptBinMetadata,
22	  deriveBinIpnsKeypair,
23	  type BinEntry,
24	  type RecycleBinMetadata,
25	  type FolderChild,
26	  type FilePointer,
27	  type FolderEntry,
28	} from '@cipherbox/core';
29	import { bytesToHex, clearBytes, hexToBytes, unwrapKey, wrapKey } from '@cipherbox/crypto';
30	import type { FolderTree } from '../state/folder-tree';
31	import { reencryptFileMetadataForFolderChange } from '../reencrypt';
32	
33	/** Current bin metadata version. */
34	const BIN_METADATA_VERSION = 'v1' as const;
35	
36	/**
37	 * Context for bin operations. Replaces Zustand store access.
38	 */
39	export type BinOperationContext = {
40	  ctx: SdkContext;
41	  userPrivateKey: Uint8Array;
42	  userPublicKey: Uint8Array;
43	  rootFolderKey: Uint8Array;
44	  teeKeys?: TeeKeys;
45	};
46	
47	/**
48	 * Internal state for the bin (replaces useBinStore).
49	 */
50	export type BinState = {
51	  entries: BinEntry[];
52	  sequenceNumber: number;
53	  ipnsName: string;
54	};
55	
56	// ---------------------------------------------------------------------------
57	// Internal helpers: load / save bin metadata
58	// ---------------------------------------------------------------------------
59	
60	/**
61	 * Load and decrypt bin metadata from IPNS.
62	 */
63	async function loadBinMetadataInternal(params: {
64	  userPrivateKey: Uint8Array;
65	  ctx: SdkContext;
66	}): Promise<{
67	  metadata: RecycleBinMetadata;
68	  ipnsName: string;
69	  sequenceNumber: bigint;
70	} | null> {
71	  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
72	  const resolved = await sdkCore.resolveIpnsRecord(binIpns.ipnsName, params.ctx);
73	
74	  if (!resolved) return null;
75	
76	  const encryptedBytes = await sdkCore.fetchFromIpfs(params.ctx, resolved.cid);
77	  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
78	
79	  return {
80	    metadata,
81	    ipnsName: binIpns.ipnsName,
82	    sequenceNumber: resolved.sequenceNumber,
83	  };
84	}
85	
86	/**
87	 * Encrypt and publish bin metadata to IPNS.
88	 */
89	async function saveBinMetadata(params: {
90	  metadata: RecycleBinMetadata;
91	  binCtx: BinOperationContext;
92	}): Promise<void> {
93	  const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
94	
95	  // Encrypt metadata with user's public key (ECIES)
96	  const encryptedBytes = await encryptBinMetadata(params.metadata, params.binCtx.userPublicKey);
97	
98	  // Pin to IPFS
99	  const { cid } = await sdkCore.addToIpfs(params.binCtx.ctx, encryptedBytes);
100	
101	  // TEE enrollment (optional)
102	  let encryptedIpnsKey: string | undefined;
103	  let keyEpoch: number | undefined;
104	
105	  if (params.binCtx.teeKeys?.currentPublicKey) {
106	    try {
107	      const teePublicKey = hexToBytes(params.binCtx.teeKeys.currentPublicKey);
108	      const wrappedKey = await wrapKey(binIpns.privateKey, teePublicKey);
109	      encryptedIpnsKey = bytesToHex(wrappedKey);
110	      keyEpoch = params.binCtx.teeKeys.currentEpoch;
111	    } catch {
112	      // TEE enrollment failure is non-blocking
113	    }
114	  }
115	
116	  // Publish IPNS record with verification
117	  await publishWithVerify({
118	    ipnsName: binIpns.ipnsName,
119	    ipnsPrivateKey: binIpns.privateKey,
120	    cid,
121	    sequenceNumber: BigInt(params.metadata.sequenceNumber),
122	    encryptedIpnsPrivateKey: encryptedIpnsKey,
123	    keyEpoch,
124	    ctx: params.binCtx.ctx,
125	  });
126	}
127	
128	/**
129	 * Publish an IPNS record and verify it is resolvable.
130	 *
131	 * Wraps createAndPublishIpnsRecord with a resolve-back verification loop.
132	 * On verify failure, retries with exponential backoff (500ms, 1000ms, 2000ms).
133	 * After all retries exhausted, does NOT throw -- the publish went through,
134	 * verification just couldn't confirm propagation.
135	 */
136	async function publishWithVerify(params: {
137	  ipnsName: string;
138	  ipnsPrivateKey: Uint8Array;
139	  cid: string;
140	  sequenceNumber: bigint;
141	  encryptedIpnsPrivateKey?: string;
142	  keyEpoch?: number;
143	  ctx: SdkContext;
144	  maxRetries?: number;
145	}): Promise<void> {
146	  const maxRetries = params.maxRetries ?? 3;
147	  // Publish once -- the API call is idempotent but no need to repeat it
148	  await sdkCore.createAndPublishIpnsRecord({
149	    ipnsPrivateKey: params.ipnsPrivateKey,
150	    ipnsName: params.ipnsName,
151	    metadataCid: params.cid,
152	    sequenceNumber: params.sequenceNumber,
153	    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
154	    keyEpoch: params.keyEpoch,
155	    ctx: params.ctx,
156	  });
157	  // Verify with retries: resolve back to confirm DB cache was written
158	  for (let attempt = 0; attempt < maxRetries; attempt++) {
159	    const resolved = await sdkCore.resolveIpnsRecord(params.ipnsName, params.ctx);
160	    if (resolved) return;
161	    if (attempt < maxRetries - 1) {
162	      await new Promise((r) => setTimeout(r, 500 * Math.pow(2, attempt)));
163	    }
164	  }
165	  // After all retries, don't throw -- the publish went through, just verification failed.
166	  // The record may still propagate eventually.
167	}
168	
169	// ---------------------------------------------------------------------------
170	// Public API
171	// ---------------------------------------------------------------------------
172	
173	/** Number of resolve attempts in loadBin before falling back to empty state. */
174	const LOAD_BIN_MAX_ATTEMPTS = 6;
175	/** Base backoff (ms) between loadBin resolve retries. */
176	const LOAD_BIN_RETRY_DELAY_MS = 500;
177	
178	/**
179	 * Load the recycle bin metadata from IPNS.
180	 *
181	 * If no bin IPNS record exists yet (first login / never deleted anything),
182	 * returns an in-memory empty BinState so that deleteToBin can create the first
183	 * record. The first addToBin lazily publishes the real record at
184	 * sequenceNumber 1 (0 + 1), which matches the API create-path.
185	 *
186	 * Crucially, loadBin NEVER publishes on a null resolve. A null is not a
187	 * reliable "bin is empty" signal: resolveIpnsRecord also returns null on a
188	 * cold-cache miss right after a page reload, or while a concurrent
189	 * loadBin()/delete is mid-flight. Publishing an empty record here is
190	 * destructive — the bin publish path carries no expectedSequenceNumber, so the
191	 * API blindly increments the sequence and overwrites the real record's CID with
192	 * the empty-bin CID (apps/api ipns.service upsertFolderIpns), wiping every
193	 * entry. The API's /ipns/resolve already falls back to its synchronously-written
194	 * DB cache, so a client-side null means the record is genuinely absent at that
195	 * instant; we recover transient nulls with a bounded retry instead of writing.
196	 *
197	 * @returns Current bin state (never null — in-memory empty state if no record exists)
198	 */
199	export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
200	  // Bounded retry: convert a transient null (cold resolve cache after reload, or
201	  // a concurrent in-flight publish) into a successful load before falling back
202	  // to empty state. Never publishes.
203	  for (let attempt = 0; attempt < LOAD_BIN_MAX_ATTEMPTS; attempt++) {
204	    const loaded = await loadBinMetadataInternal({
205	      userPrivateKey: params.binCtx.userPrivateKey,
206	      ctx: params.binCtx.ctx,
207	    });
208	
209	    if (loaded) {
210	      return {
211	        entries: loaded.metadata.entries,
212	        sequenceNumber: loaded.metadata.sequenceNumber,
213	        ipnsName: loaded.ipnsName,
214	      };
215	    }
216	
217	    if (attempt < LOAD_BIN_MAX_ATTEMPTS - 1) {
218	      await new Promise((r) => setTimeout(r, LOAD_BIN_RETRY_DELAY_MS));
219	    }
220	  }
221	
222	  // No bin IPNS record resolved after all retries — treat as a genuinely new
223	  // bin. Return in-memory empty state WITHOUT publishing. The first addToBin
224	  // publishes at sequenceNumber 0 + 1 = 1, matching the API create-path.
225	  const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
226	  return {
227	    entries: [],
228	    sequenceNumber: 0,
229	    ipnsName: binIpns.ipnsName,
230	  };
231	}
232	
233	/**
234	 * Add item to recycle bin.
235	 *
236	 * Removes the item from the folder metadata (via deleteFromFolder),
237	 * creates a BinEntry, appends to bin metadata, and publishes both.
238	 *
239	 * @returns The removed item from the folder
240	 */
241	export async function addToBin(params: {
242	  folderIpnsName: string;
243	  childId: string;
244	  parentPath: string;
245	  folderTree: FolderTree;
246	  binState: BinState;
247	  binCtx: BinOperationContext;
248	}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
249	  const folder = params.folderTree.get(params.folderIpnsName);
250	  if (!folder) throw new Error('Folder not loaded');
251	
252	  // 1. Remove item from folder metadata
253	  const baseChildren = [...folder.children];
254	  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
255	    children: folder.children,
256	    childId: params.childId,
257	  });
258	
259	  // Capture the source folder's folderKey (the key the file's FileMetadata is
260	  // encrypted under) wrapped for the vault, so restore can re-encrypt to any
261	  // destination later even if this parent folder is gone by then. Files only —
262	  // a restored folder carries its own folderKey in its FolderEntry. Computed
263	  // BEFORE the publish so a wrapKey failure aborts before any folder/bin
264	  // mutation, avoiding a split state where the file is removed from the folder
265	  // but never recorded in the bin.
266	  const isFile = removedItem.type === 'file';
267	  const originalFolderKeyEncrypted = isFile
268	    ? bytesToHex(await wrapKey(folder.folderKey, params.binCtx.userPublicKey))
269	    : undefined;
270	
271	  // 2. Publish updated folder metadata
272	  const { newSequenceNumber, publishedChildren } = await sdkCore.updateFolderMetadataAndPublish({
273	    children: updatedChildren,
274	    baseChildren,
275	    folderKey: folder.folderKey,
276	    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
277	    ipnsName: params.folderIpnsName,
278	    sequenceNumber: folder.sequenceNumber,
279	    ctx: params.binCtx.ctx,
280	  });
281	
282	  // 3. Update folder state — adopt merged published set (CR-01)
283	  folder.children = publishedChildren;
284	  folder.sequenceNumber = newSequenceNumber;
285	  folder.lastLoadedAt = Date.now();
286	  params.folderTree.set(params.folderIpnsName, folder);
287	
288	  // 4. Build bin entry (isFile / originalFolderKeyEncrypted computed above,
289	  //    before the publish).
290	  const entry: BinEntry = {
291	    id: crypto.randomUUID(),
292	    itemType: isFile ? 'file' : 'folder',
293	    name: removedItem.name,
294	    originalParentIpnsName: params.folderIpnsName,
295	    originalPath: params.parentPath,
296	    deletedAt: Date.now(),
297	    size: 0,
298	    mimeType: '',
299	    filePointer: isFile ? (removedItem as FilePointer) : undefined,
300	    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
301	    originalFolderKeyEncrypted,
302	  };
303	
304	  // 5. Update bin metadata and publish
305	  const updatedEntries = [...params.binState.entries, entry];
306	  const newBinSeq = params.binState.sequenceNumber + 1;
307	
308	  const metadata: RecycleBinMetadata = {
309	    version: BIN_METADATA_VERSION,
310	    sequenceNumber: newBinSeq,
311	    entries: updatedEntries,
312	  };
313	
314	  await saveBinMetadata({ metadata, binCtx: params.binCtx });
315	
316	  const updatedBinState: BinState = {
317	    entries: updatedEntries,
318	    sequenceNumber: newBinSeq,
319	    ipnsName: params.binState.ipnsName,
320	  };
321	
322	  return { removedItem, updatedBinState };
323	}
324	
325	/**
326	 * Restore an item from the recycle bin back to a folder.
327	 *
328	 * Removes the entry from bin metadata, adds the preserved FolderChild
329	 * back to the target folder's children, and publishes both.
330	 */
331	export async function restoreFromBin(params: {
332	  entryId: string;
333	  targetFolderIpnsName: string;
334	  folderTree: FolderTree;
335	  binState: BinState;
336	  binCtx: BinOperationContext;
337	}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
338	  // 1. Find the bin entry
339	  const entry = params.binState.entries.find((e) => e.id === params.entryId);
340	  if (!entry) throw new Error('Bin entry not found');
341	
342	  // 2. Get the FolderChild to restore
343	  let child: FolderChild;
344	  if (entry.itemType === 'file' && entry.filePointer) {
345	    child = { ...entry.filePointer, modifiedAt: Date.now() };
346	  } else if (entry.itemType === 'folder' && entry.folderEntry) {
347	    child = { ...entry.folderEntry, modifiedAt: Date.now() };
348	  } else {
349	    throw new Error('Bin entry has no stored item reference');
350	  }
351	
352	  // 3. Add child back to target folder
353	  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
354	  if (!targetFolder) throw new Error('Target folder not loaded');
355	
356	  // A retry of a partially-applied restore (the bin entry survives a step-5b /
357	  // step-6 failure) can find this child already listed in the target from the prior
358	  // attempt's publish. Drop any prior copy by id so the restore is idempotent —
359	  // re-running REPLACES rather than duplicates the listing — and exclude it from the
360	  // name-collision check so the file isn't spuriously renamed against itself. The
361	  // no-conflict publish path doesn't dedup by id (only the 409 merge does), so a
362	  // same-id duplicate appended here would otherwise persist.
363	  const targetChildrenSansChild = targetFolder.children.filter((c) => c.id !== child.id);
364	
365	  // Handle name collisions (against other entries only)
366	  const existingNames = new Set(targetChildrenSansChild.map((c) => c.name));
367	  if (existingNames.has(child.name)) {
368	    let newName = `${child.name} (restored)`;
369	    let counter = 2;
370	    while (existingNames.has(newName)) {
371	      newName = `${child.name} (restored ${counter})`;
372	      counter++;
373	    }
374	    child = { ...child, name: newName };
375	  }
376	
377	  // 3b. Decide whether this restore must re-encrypt the file's FileMetadata to
378	  // the target folderKey: only for a FILE restored to a DIFFERENT folder than its
379	  // original parent. The record is AES-256-GCM sealed with the parent folderKey,
380	  // and addToBin stores the FilePointer verbatim without re-keying; restoring to a
381	  // folder with a different folderKey without re-encrypting would make the file
382	  // undecryptable (CryptoError: Decryption failed) — the same class of bug as
383	  // moveItem. Restoring in place (target === original parent, the default UI flow)
384	  // leaves the key unchanged, so no re-encrypt is needed.
385	  //
386	  // Validate the preconditions NOW, before publishing, so a restore that is
387	  // guaranteed to fail (missing file IPNS key, or a legacy entry whose source key
388	  // can't be recovered) aborts cleanly without leaving an undecryptable listing in
389	  // the target. The actual re-key — unwrap + network resolve/publish — runs AFTER
390	  // the target folder is durably published (step 5b), mirroring moveItem: the
391	  // metadata is only re-keyed once the target listing is durable, so at every
392	  // intermediate failure the file stays readable from somewhere that lists it under
393	  // the matching key (the bin, by the source key, before the re-key; the target, by
394	  // the target key, after it) — never readable from neither.
395	  const mustReencrypt =
396	    entry.itemType === 'file' &&
397	    !!entry.filePointer &&
398	    params.targetFolderIpnsName !== entry.originalParentIpnsName;
399	  if (mustReencrypt) {
400	    if (!entry.filePointer!.ipnsPrivateKeyEncrypted) {
401	      throw new Error('Cannot re-encrypt file metadata on restore: missing file IPNS key');
402	    }
403	    // Source key = the folderKey the FileMetadata is currently sealed under.
404	    // Recoverable from the key captured at delete time (works even if the original
405	    // parent is gone), or — for legacy entries created before that capture — from
406	    // the still-loaded original parent folder.
407	    if (!entry.originalFolderKeyEncrypted && !params.folderTree.get(entry.originalParentIpnsName)) {
408	      throw new Error(
409	        'Original parent folder must be loaded to restore a legacy file to a different folder'
410	      );
411	    }
412	  }
413	
414	  const baseChildren = [...targetFolder.children];
415	  const updatedFolderChildren = [...targetChildrenSansChild, child];
416	
417	  // 4. Publish target folder first (add-before-remove): the file is listed in the
418	  //    target while still recorded in the bin, so it is never lost mid-restore.
419	  const { newSequenceNumber, publishedChildren } = await sdkCore.updateFolderMetadataAndPublish({
420	    children: updatedFolderChildren,
421	    baseChildren,
422	    folderKey: targetFolder.folderKey,
423	    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
424	    ipnsName: params.targetFolderIpnsName,
425	    sequenceNumber: targetFolder.sequenceNumber,
426	    ctx: params.binCtx.ctx,
427	  });
428	
429	  // 5. Update folder state — adopt merged published set (CR-01)
430	  targetFolder.children = publishedChildren;
431	  targetFolder.sequenceNumber = newSequenceNumber;
432	  targetFolder.lastLoadedAt = Date.now();
433	  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
434	
435	  // 5b. Re-key the FileMetadata to the target folderKey, now that the target
436	  //     listing is durable (see step 3b). Idempotent via
437	  //     reencryptFileMetadataForFolderChange: a retry after a partial failure that
438	  //     already re-keyed the record completes cleanly instead of throwing.
439	  if (mustReencrypt) {
440	    // Only freshly-unwrapped key material is cleared in `finally` — never the
441	    // shared folderTree key from the legacy fallback, which the tree still owns.
442	    let unwrappedSourceFolderKey: Uint8Array | undefined;
443	    let fileIpnsPrivateKey: Uint8Array | undefined;
444	    try {
445	      // Both guaranteed by the precondition check above; re-narrowed here for the
446	      // type-checker and as defense in depth.
447	      const filePointer = entry.filePointer;
448	      const ipnsPrivateKeyEncrypted = filePointer?.ipnsPrivateKeyEncrypted;
449	      if (!filePointer || !ipnsPrivateKeyEncrypted) {
450	        throw new Error('Cannot re-encrypt file metadata on restore: missing file IPNS key');
451	      }
452	
453	      let sourceFolderKey: Uint8Array;
454	      if (entry.originalFolderKeyEncrypted) {
455	        unwrappedSourceFolderKey = await unwrapKey(
456	          hexToBytes(entry.originalFolderKeyEncrypted),
457	          params.binCtx.userPrivateKey
458	        );
459	        sourceFolderKey = unwrappedSourceFolderKey;
460	      } else {
461	        const sourceFolder = params.folderTree.get(entry.originalParentIpnsName);
462	        if (!sourceFolder) {
463	          throw new Error(
464	            'Original parent folder must be loaded to restore a legacy file to a different folder'
465	          );
466	        }
467	        sourceFolderKey = sourceFolder.folderKey;
468	      }
469	
470	      fileIpnsPrivateKey = await unwrapKey(
471	        hexToBytes(ipnsPrivateKeyEncrypted),
472	        params.binCtx.userPrivateKey
473	      );
474	      await reencryptFileMetadataForFolderChange({
475	        fileMetaIpnsName: filePointer.fileMetaIpnsName,
476	        fileIpnsPrivateKey,
477	        sourceFolderKey,
478	        destFolderKey: targetFolder.folderKey,
479	        ctx: params.binCtx.ctx,
480	      });
481	    } finally {
482	      if (unwrappedSourceFolderKey) clearBytes(unwrappedSourceFolderKey);
483	      if (fileIpnsPrivateKey) clearBytes(fileIpnsPrivateKey);
484	    }
485	  }
486	
487	  // 6. Remove entry from bin and publish
488	  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
489	  const newBinSeq = params.binState.sequenceNumber + 1;
490	
491	  const metadata: RecycleBinMetadata = {
492	    version: BIN_METADATA_VERSION,
493	    sequenceNumber: newBinSeq,
494	    entries: remainingEntries,
495	  };
496	
497	  await saveBinMetadata({ metadata, binCtx: params.binCtx });
498	
499	  const updatedBinState: BinState = {
500	    entries: remainingEntries,
501	    sequenceNumber: newBinSeq,
502	    ipnsName: params.binState.ipnsName,
503	  };
504	
505	  return { restoredItem: child, updatedBinState };
506	}
507	
508	/**
509	 * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
510	 *
511	 * For files: unpins the content CID if available.
512	 * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
513	 */
514	export async function permanentDeleteFromBin(params: {
515	  entryId: string;
516	  binState: BinState;
517	  binCtx: BinOperationContext;
518	}): Promise<{ updatedBinState: BinState }> {
519	  const entry = params.binState.entries.find((e) => e.id === params.entryId);
520	  if (!entry) throw new Error('Bin entry not found');
521	
522	  // Unpin content CID if available (best-effort)
523	  if (entry.contentCid) {
524	    try {
525	      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
526	    } catch {
527	      // Best-effort CID cleanup
528	    }
529	  }
530	
531	  // Remove from bin metadata and publish
532	  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
533	  const newBinSeq = params.binState.sequenceNumber + 1;
534	
535	  const metadata: RecycleBinMetadata = {
536	    version: BIN_METADATA_VERSION,
537	    sequenceNumber: newBinSeq,
538	    entries: remainingEntries,
539	  };
540	
541	  await saveBinMetadata({ metadata, binCtx: params.binCtx });
542	
543	  return {
544	    updatedBinState: {
545	      entries: remainingEntries,
546	      sequenceNumber: newBinSeq,
547	      ipnsName: params.binState.ipnsName,
548	    },
549	  };
550	}
551	
552	/**
553	 * Empty the bin by permanently deleting all entries.
554	 *
555	 * Cleans up CIDs (best-effort) and publishes empty bin metadata.
556	 */
557	export async function emptyBin(params: {
558	  binState: BinState;
559	  binCtx: BinOperationContext;
560	}): Promise<{ updatedBinState: BinState }> {
561	  // Best-effort CID cleanup for each entry
562	  for (const entry of params.binState.entries) {
563	    if (entry.contentCid) {
564	      try {
565	        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
566	      } catch {
567	        // Non-blocking
568	      }
569	    }
570	  }
571	
572	  // Publish empty bin metadata
573	  const newBinSeq = params.binState.sequenceNumber + 1;
574	  const metadata: RecycleBinMetadata = {
575	    version: BIN_METADATA_VERSION,
576	    sequenceNumber: newBinSeq,
577	    entries: [],
578	  };
579	
580	  await saveBinMetadata({ metadata, binCtx: params.binCtx });
581	
582	  return {
583	    updatedBinState: {
584	      entries: [],
585	      sequenceNumber: newBinSeq,
586	      ipnsName: params.binState.ipnsName,
587	    },
588	  };
589	}
590	
591	/**
592	 * Purge expired bin entries based on retention period.
593	 *
594	 * Filters entries past their retention, cleans up CIDs (best-effort),
595	 * and publishes updated bin metadata in a single IPNS publish.
596	 *
597	 * @returns Number of purged entries and updated bin state
598	 */
599	export async function purgeExpiredEntries(params: {
600	  binState: BinState;
601	  retentionDays: number;
602	  binCtx: BinOperationContext;
603	}): Promise<{ purgedCount: number; updatedState: BinState }> {
604	  const retentionMs = params.retentionDays * 24 * 60 * 60 * 1000;
605	  const now = Date.now();
606	
607	  const expired = params.binState.entries.filter((e) => now - e.deletedAt > retentionMs);
608	  if (expired.length === 0) {
609	    return { purgedCount: 0, updatedState: params.binState };
610	  }
611	
612	  // Remove expired entries and publish updated bin BEFORE cleanup.
613	  // This ensures bin metadata is consistent even if CID unpins fail.
614	  const expiredIds = new Set(expired.map((e) => e.id));
615	  const remainingEntries = params.binState.entries.filter((e) => !expiredIds.has(e.id));
616	  const newBinSeq = params.binState.sequenceNumber + 1;
617	
618	  const metadata: RecycleBinMetadata = {
619	    version: BIN_METADATA_VERSION,
620	    sequenceNumber: newBinSeq,
621	    entries: remainingEntries,
622	  };
623	
624	  await saveBinMetadata({ metadata, binCtx: params.binCtx });
625	
626	  // Best-effort CID cleanup for expired entries (after metadata is saved)
627	  for (const entry of expired) {
628	    if (entry.contentCid) {
629	      try {
630	        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
631	      } catch {
632	        // Best-effort: CID cleanup failures are non-blocking
633	      }
634	    }
635	    // Also clean up version CIDs to recover quota
636	    if (entry.versionCids) {
637	      for (const vc of entry.versionCids) {
638	        try {
639	          await sdkCore.unpinFromIpfs(params.binCtx.ctx, vc.cid);
640	        } catch {
641	          // Best-effort
642	        }
643	      }
644	    }
645	  }
646	
647	  return {
648	    purgedCount: expired.length,
649	    updatedState: {
650	      entries: remainingEntries,
651	      sequenceNumber: newBinSeq,
652	      ipnsName: params.binState.ipnsName,
653	    },
654	  };
655	}
