1	use fuser::ReplyEmpty;
2	use std::ffi::OsStr;
3	use std::time::SystemTime;
4	
5	use crate::helpers::is_platform_special;
6	use crate::inode::InodeKind;
7	use crate::CipherBoxFS;
8	
9	/// Rename or move a file/folder.
10	pub fn handle_rename(
11	    fs: &mut CipherBoxFS,
12	    parent: u64,
13	    name: &OsStr,
14	    newparent: u64,
15	    newname: &OsStr,
16	    reply: ReplyEmpty,
17	) {
18	    log::debug!(
19	        "rename: {:?} (parent {}) -> {:?} (parent {})",
20	        name,
21	        parent,
22	        newname,
23	        newparent,
24	    );
25	    let name_str = match name.to_str() {
26	        Some(n) => n,
27	        None => {
28	            reply.error(libc::EINVAL);
29	            return;
30	        }
31	    };
32	    let newname_str = match newname.to_str() {
33	        Some(n) => n,
34	        None => {
35	            reply.error(libc::EINVAL);
36	            return;
37	        }
38	    };
39	
40	    // Find source inode (with FUSE-T truncated name fallback)
41	    let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
42	        Some(ino) => (ino, name_str.to_string()),
43	        None => {
44	            let parent_inode = match fs.inodes.get(parent) {
45	                Some(i) => i,
46	                None => {
47	                    reply.error(libc::ENOENT);
48	                    return;
49	                }
50	            };
51	            let children = parent_inode.children.clone().unwrap_or_default();
52	            let mut matches: Vec<(u64, String)> = Vec::new();
53	            for &child_ino in &children {
54	                if let Some(child) = fs.inodes.get(child_ino) {
55	                    if is_platform_special(&child.name) {
56	                        continue;
57	                    }
58	                    if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
59	                        matches.push((child_ino, child.name.clone()));
60	                    }
61	                }
62	            }
63	            if matches.len() == 1 {
64	                log::debug!(
65	                    "rename suffix-match: truncated {:?} matched full name {:?}",
66	                    name_str,
67	                    matches[0].1
68	                );
69	                (matches[0].0, matches[0].1.clone())
70	            } else {
71	                log::debug!(
72	                    "rename failed: {:?} not found (suffix matches: {})",
73	                    name_str,
74	                    matches.len()
75	                );
76	                reply.error(libc::ENOENT);
77	                return;
78	            }
79	        }
80	    };
81	
82	    let name_str = &actual_name;
83	
84	    log::debug!(
85	        "rename: {} (ino {}) in parent {} -> {} in parent {}",
86	        name_str,
87	        source_ino,
88	        parent,
89	        newname_str,
90	        newparent,
91	    );
92	
93	    // Cross-folder FILE moves must re-encrypt the per-file FileMetadata to the
94	    // destination folderKey (it is sealed with the parent folderKey). Capture
95	    // the inputs now, before any inode mutation. Folder moves need nothing — a
96	    // folder keeps its own key, as do the files inside it.
97	    let reencrypt_inputs: Option<(
98	        String,
99	        zeroize::Zeroizing<Vec<u8>>,
100	        zeroize::Zeroizing<Vec<u8>>,
101	        zeroize::Zeroizing<Vec<u8>>,
102	    )> = if parent != newparent {
103	        match fs.inodes.get(source_ino).map(|i| &i.kind) {
104	            Some(InodeKind::File {
105	                file_meta_ipns_name: Some(meta_ipns),
106	                file_ipns_private_key: Some(key),
107	                ..
108	            }) if !meta_ipns.is_empty() => {
109	                match (fs.get_folder_key(parent), fs.get_folder_key(newparent)) {
110	                    (Some(src_key), Some(dst_key)) => {
111	                        Some((meta_ipns.clone(), key.clone(), src_key, dst_key))
112	                    }
113	                    _ => {
114	                        log::warn!(
115	                                "rename: cross-folder move missing folder key(s) for ino {}; skipping metadata re-encrypt",
116	                                source_ino
117	                            );
118	                        None
119	                    }
120	                }
121	            }
122	            Some(InodeKind::File { .. }) => {
123	                log::warn!(
124	                        "rename: cross-folder file move for ino {} missing IPNS name/key; skipping metadata re-encrypt",
125	                        source_ino
126	                    );
127	                None
128	            }
129	            _ => None,
130	        }
131	    } else {
132	        None
133	    };
134	
135	    // If destination exists, handle replacement
136	    if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
137	        // Self-replace (rename "a" to "a" in same dir): no-op
138	        if dest_ino == source_ino {
139	            reply.ok();
140	            return;
141	        }
142	
143	        if let Some(dest_inode) = fs.inodes.get(dest_ino) {
144	            // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
145	            let source_is_dir = fs
146	                .inodes
147	                .get(source_ino)
148	                .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
149	                .unwrap_or(false);
150	            let dest_is_dir = matches!(
151	                dest_inode.kind,
152	                InodeKind::Root { .. } | InodeKind::Folder { .. }
153	            );
154	            if source_is_dir && !dest_is_dir {
155	                reply.error(libc::ENOTDIR);
156	                return;
157	            }
158	            if !source_is_dir && dest_is_dir {
159	                reply.error(libc::EISDIR);
160	                return;
161	            }
162	
163	            match &dest_inode.kind {
164	                InodeKind::Folder { .. } => {
165	                    if let Some(ref children) = dest_inode.children {
166	                        if !children.is_empty() {
167	                            reply.error(libc::ENOTEMPTY);
168	                            return;
169	                        }
170	                    }
171	                }
172	                InodeKind::File { cid, .. } => {
173	                    if !cid.is_empty() {
174	                        let cid_clone = cid.clone();
175	                        let api = fs.api.clone();
176	                        fs.rt.spawn(async move {
177	                            let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid_clone)
178	                                .await;
179	                        });
180	                    }
181	                }
182	                _ => {}
183	            }
184	        }
185	        fs.publish_queue.remove(&dest_ino);
186	        fs.inodes.remove(dest_ino);
187	    }
188	
189	    // Remove source from old parent's name index (NFC-normalized)
190	    {
191	        use unicode_normalization::UnicodeNormalization;
192	        let nfc_key: String = name_str.nfc().collect();
193	        fs.inodes.name_to_ino.remove(&(parent, nfc_key));
194	    }
195	
196	    // Update the source inode's name and parent
197	    if let Some(inode) = fs.inodes.get_mut(source_ino) {
198	        inode.name = newname_str.to_string();
199	        inode.parent_ino = newparent;
200	        inode.attr.ctime = SystemTime::now();
201	    }
202	
203	    // Update the name lookup index for the new location (NFC-normalized)
204	    {
205	        use unicode_normalization::UnicodeNormalization;
206	        let nfc_key: String = newname_str.nfc().collect();
207	        fs.inodes
208	            .name_to_ino
209	            .insert((newparent, nfc_key), source_ino);
210	    }
211	
212	    if parent != newparent {
213	        if let Some(old_parent) = fs.inodes.get_mut(parent) {
214	            if let Some(ref mut children) = old_parent.children {
215	                children.retain(|&c| c != source_ino);
216	            }
217	            old_parent.attr.mtime = SystemTime::now();
218	            old_parent.attr.ctime = SystemTime::now();
219	        }
