const fs = require('fs');

const OUT = '/private/tmp/claude-501/-Users-myankelev-Code-random-cipher-box/2c9cca7a-f210-45f4-b940-4f091be387a8/tasks/wmvb8x559.output';
const PAGE = '/Users/myankelev/Code/random/cipher-box/landing/src/pages/explainer.astro';

const parsed = JSON.parse(fs.readFileSync(OUT, 'utf8'));
const R = parsed.result;

function decode(s) {
  return s
    .replace(/&gt;/g, '>')
    .replace(/&lt;/g, '<')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, '’')   // apostrophe -> curly, never break single-quoted JS
    .replace(/&apos;/g, '’')
    .replace(/&#x27;/gi, '’')
    .replace(/&amp;/g, '&');
}

function extractArray(field) {
  let text = field;
  // prefer a fenced code block that contains the array
  const fences = [...field.matchAll(/```[a-zA-Z]*\n([\s\S]*?)```/g)].map((m) => m[1]);
  const fenced = fences.find((f) => /\bid:\s*['"`]/.test(f) && /\[\s*\{/.test(f));
  if (fenced) text = fenced;
  const m = text.match(/\[\s*\{/);
  if (!m) throw new Error('no array start found');
  const start = m.index;
  const end = text.lastIndexOf(']');
  if (end <= start) throw new Error('no array end found');
  return decode(text.slice(start, end + 1));
}

// validation sandbox
const L = (t = '', k = '') => ({ t, k });
const V = new Proxy({}, { get: () => 'X' });
function validate(arr) {
  // eslint-disable-next-line no-new-func
  const fn = new Function('L', 'V', 'return ' + arr + ';');
  const res = fn(L, V);
  if (!Array.isArray(res)) throw new Error('not an array');
  return res;
}

const fields = {
  structure: R.structure,
  moveDelete: R.moveDelete,
  sharingGrants: R.sharingGrants,
  permMoves: R.permMoves,
  permRenameDelSw: R.permRenameDelSw,
};

const extracted = {};
let failed = false;
for (const [name, val] of Object.entries(fields)) {
  try {
    const arr = extractArray(val);
    const res = validate(arr);
    extracted[name] = arr;
    console.log(`[ok] ${name}: ${res.length} flows -> ${res.map((f) => f.id).join(', ')}`);
  } catch (e) {
    failed = true;
    console.log(`[FAIL] ${name}: ${e.message}`);
  }
}

if (failed) {
  console.log('\nAborting — fix the failing field(s) before patching.');
  process.exit(1);
}

const inner = (a) => a.trim().replace(/^\[/, '').replace(/\]$/, '').trim().replace(/,\s*$/, '');
const coreMerged = '[\n' + inner(extracted.structure) + ',\n' + inner(extracted.moveDelete) + '\n]';
// validate merged
validate(coreMerged);

let page = fs.readFileSync(PAGE, 'utf8');
const repl = [
  ['const coreFlows = [];', 'const coreFlows = ' + coreMerged + ';'],
  ['const sharingFlows = [];', 'const sharingFlows = ' + extracted.sharingGrants + ';'],
  ['const permMoveFlows = [];', 'const permMoveFlows = ' + extracted.permMoves + ';'],
  ['const permRenameFlows = [];', 'const permRenameFlows = ' + extracted.permRenameDelSw + ';'],
];
for (const [from, to] of repl) {
  if (!page.includes(from)) throw new Error('placeholder not found: ' + from);
  page = page.replace(from, to);
}
fs.writeFileSync(PAGE, page);
console.log('\nPatched ' + PAGE);

